// FlowDesk launcher / setup / uninstall. Windows x64, standard library only.
// Build: GOOS=windows GOARCH=amd64 CGO_ENABLED=0 go build -trimpath -ldflags="-s -w" -o FlowDesk-Setup-v1.1.exe main.go
package main
import (
 "bufio"
 _ "embed"
 "errors"
 "fmt"
 "net/url"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "syscall"
 "unsafe"
)
//go:embed FlowDesk.ico
var icon []byte
var input=bufio.NewReader(os.Stdin)
func ask(q string) string {fmt.Print(q); s,_:=input.ReadString('\n'); return strings.TrimSpace(s)}
func yes(q string)bool{return strings.EqualFold(ask(q+" [y/N]: "),"y")}
func dir()string{p:=os.Getenv("ProgramFiles");if p==""{p=`C:\Program Files`};return filepath.Join(p,"FlowDesk")}
func dataDir()string{return filepath.Join(os.Getenv("LOCALAPPDATA"),"FlowDesk","BrowserData")}
func command(name string,args ...string)error{c:=exec.Command(name,args...);c.Stdout=os.Stdout;c.Stderr=os.Stderr;return c.Run()}
func ps(script string,env ...string)error{c:=exec.Command("powershell.exe","-NoProfile","-NonInteractive","-Command",script);c.Env=append(os.Environ(),env...);c.Stdout=os.Stdout;c.Stderr=os.Stderr;return c.Run()}
func approvedURL(raw string)(string,error){u,e:=url.Parse(raw);if e!=nil||u.Scheme!="https"||u.Hostname()==""||u.User!=nil||u.Fragment!=""||u.RawQuery!=""{return "",errors.New("Enter the full HTTPS address of your published FlowDesk website, without a query or fragment.")};return strings.TrimRight(u.String(),"/")+"/",nil}
func elevated()bool{var sid *byte; adv:=syscall.NewLazyDLL("advapi32.dll"); allocate:=adv.NewProc("AllocateAndInitializeSid");free:=adv.NewProc("FreeSid");check:=adv.NewProc("CheckTokenMembership");authority:=[6]byte{0,0,0,0,0,5};r,_,_:=allocate.Call(uintptr(unsafe.Pointer(&authority[0])),2,32,544,0,0,0,0,0,0,uintptr(unsafe.Pointer(&sid)));if r==0{return false};defer free.Call(uintptr(unsafe.Pointer(sid)));var member int32;r,_,_=check.Call(0,uintptr(unsafe.Pointer(sid)),uintptr(unsafe.Pointer(&member)));return r!=0&&member!=0}
func elevate()error{self,e:=os.Executable();if e!=nil{return e};verb,_:=syscall.UTF16PtrFromString("runas");file,_:=syscall.UTF16PtrFromString(self);args,_:=syscall.UTF16PtrFromString("--elevated");r,_,_:=syscall.NewLazyDLL("shell32.dll").NewProc("ShellExecuteW").Call(0,uintptr(unsafe.Pointer(verb)),uintptr(unsafe.Pointer(file)),uintptr(unsafe.Pointer(args)),0,1);if r<=32{return errors.New("Administrator approval was cancelled or failed")};return nil}
func edge()string{for _,k:=range []string{"ProgramFiles(x86)","ProgramFiles","LOCALAPPDATA"}{if p:=os.Getenv(k);p!=""{p=filepath.Join(p,"Microsoft","Edge","Application","msedge.exe");if _,e:=os.Stat(p);e==nil{return p}}};p,_:=exec.LookPath("msedge.exe");return p}
func setup()error{if !elevated(){if len(os.Args)>1{return errors.New("Administrator privileges are required")};return elevate()};fmt.Println("FlowDesk v1.1 | Windows setup\nInstall location: "+dir()+"\nRequires Microsoft Edge and your published HTTPS website.\nClose any existing FlowDesk window before continuing.");if edge()==""{return errors.New("Microsoft Edge is not installed")};previous,_:=os.ReadFile(filepath.Join(dir(),"website.txt"));raw:=ask("Published FlowDesk HTTPS address (Enter to keep previous): ");if raw==""{raw=strings.TrimSpace(string(previous))};site,e:=approvedURL(raw);if e!=nil{return e};if !yes("Install FlowDesk and create desktop / Start menu shortcuts?"){return nil};self,e:=os.Executable();if e!=nil{return e};bin,e:=os.ReadFile(self);if e!=nil{return e};d:=dir();if e=os.MkdirAll(d,0755);e!=nil{return e};for _,n:=range []string{"FlowDesk.exe","Uninstall.exe"}{if e=os.WriteFile(filepath.Join(d,n),bin,0755);e!=nil{return e}};if e=os.WriteFile(filepath.Join(d,"FlowDesk.ico"),icon,0644);e!=nil{return e};if e=os.WriteFile(filepath.Join(d,"website.txt"),[]byte(site),0644);e!=nil{return e};if e=ps(`$ErrorActionPreference='Stop'; $w=New-Object -ComObject WScript.Shell; foreach($folder in @([Environment]::GetFolderPath('CommonDesktopDirectory'),[Environment]::GetFolderPath('CommonPrograms'))){$s=$w.CreateShortcut((Join-Path $folder 'FlowDesk.lnk'));$s.TargetPath=Join-Path $env:FD_DIR 'FlowDesk.exe';$s.WorkingDirectory=$env:FD_DIR;$s.IconLocation=(Join-Path $env:FD_DIR 'FlowDesk.ico')+',0';$s.Save()}`,"FD_DIR="+d);e!=nil{return e};rk:=`HKLM\Software\Microsoft\Windows\CurrentVersion\Uninstall\FlowDesk`;for k,v:=range map[string]string{"DisplayName":"FlowDesk","DisplayVersion":"1.1","Publisher":"FlowDesk","InstallLocation":d,"DisplayIcon":filepath.Join(d,"FlowDesk.ico"),"UninstallString":`"`+filepath.Join(d,"Uninstall.exe")+`"`}{if e=command("reg.exe","add",rk,"/v",k,"/t","REG_SZ","/d",v,"/f");e!=nil{return e}};fmt.Println("Installation finished. Open FlowDesk from your desktop.");return nil}
func launch()error{p:=edge();if p==""{return errors.New("Microsoft Edge is required")};raw,e:=os.ReadFile(filepath.Join(dir(),"website.txt"));if e!=nil{return e};site,e:=approvedURL(strings.TrimSpace(string(raw)));if e!=nil{return e};if os.Getenv("LOCALAPPDATA")==""{return errors.New("Local application data path unavailable")};return exec.Command(p,"--app="+site,"--user-data-dir="+dataDir(),"--no-first-run").Start()}
func uninstall()error{if !elevated(){if len(os.Args)>1{return errors.New("Administrator privileges are required")};return elevate()};fmt.Println("FlowDesk v1.1 | Uninstall\nClose FlowDesk and its dedicated Edge windows first.\nBack up / sync records first. Google Drive copies will not be deleted.");if !yes("Remove FlowDesk program files and shortcuts?"){return nil};removeData:=yes("Also permanently remove the current Windows user's entire dedicated FlowDesk local profile and unsynced records?");if removeData{if os.Getenv("LOCALAPPDATA")==""{return errors.New("Local application data path unavailable")};if e:=os.RemoveAll(dataDir());e!=nil{return fmt.Errorf("Cannot delete local profile; close FlowDesk and retry: %w",e)};_ = os.Remove(filepath.Dir(dataDir()))};d:=dir();if e:=ps(`$ErrorActionPreference='Stop'; foreach($folder in @([Environment]::GetFolderPath('CommonDesktopDirectory'),[Environment]::GetFolderPath('CommonPrograms'))){$p=Join-Path $folder 'FlowDesk.lnk'; if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Force}}`);e!=nil{return e};for _,n:=range []string{"FlowDesk.exe","FlowDesk.ico","website.txt"}{if e:=os.Remove(filepath.Join(d,n));e!=nil&&!os.IsNotExist(e){return e}};rk:=`HKLM\Software\Microsoft\Windows\CurrentVersion\Uninstall\FlowDesk`;_ = command("reg.exe","delete",rk,"/f");self:=filepath.Join(d,"Uninstall.exe");if e:=ps(`$ErrorActionPreference='Stop'; $s='Start-Sleep -Seconds 2; Wait-Process -Id '+$env:FD_PID+' -ErrorAction SilentlyContinue; $p=$env:FD_SELF; Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue; $d=Split-Path -Parent $p; if((Test-Path -LiteralPath $d) -and -not (Get-ChildItem -LiteralPath $d -Force)){Remove-Item -LiteralPath $d -Force}'; $encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($s)); Start-Process powershell.exe -WindowStyle Hidden -ArgumentList '-NoProfile','-NonInteractive','-EncodedCommand',$encoded`,"FD_PID="+fmt.Sprint(os.Getpid()),"FD_SELF="+self);e!=nil{return e};fmt.Println("Uninstall scheduled to finish when this window closes. Other Windows accounts and cloud backups are not removed.");return nil}
func main(){self,_:=os.Executable();name:=strings.ToLower(filepath.Base(self));var e error;switch name{case "flowdesk.exe":e=launch();if e==nil{return};case "uninstall.exe":e=uninstall();default:e=setup()};if e!=nil{fmt.Println("Error:",e)};if e!=nil||elevated(){ask("Press Enter to close.")}}
